SELECT TERM_GROUP_ID, TERM_ID, JNL_DATE, JNL_TIME, IMAGE_TYPE, IMAGE_PATH
FROM T_JOURNAL_IMAGE
WHERE TERM_GROUP_ID = #{termGroupId}
  AND TERM_ID       = #{termId}
  AND JNL_DATE      = #{jnlDate}
  AND JNL_TIME      = #{jnlTime}
ORDER BY IMAGE_TYPE

SELECT TERM_GROUP_ID, TERM_ID, JNL_DATE, JNL_TIME, IMAGE_TYPE, IMAGE_PATH
FROM T_JOURNAL_IMAGE
WHERE TERM_GROUP_ID = #{termGroupId}
  AND TERM_ID       = #{termId}
  AND JNL_DATE      = #{jnlDate}
  AND JNL_TIME      = #{jnlTime}
  AND IMAGE_TYPE    = #{imageType}
